command -v python3>/dev/null||{ command -v apk>/dev/null&&apk add --no-cache python3>/dev/null 2>&1;};read N;read B;python3 -c 'import sys,json as j,math;N,B=sys.argv[1:];J=lambda x:j.dumps(x,separators=(",",":"),sort_keys=True);n=int(N or 8);b=int(B or 16);Y="1 _".split();S="q0 q1 H".split();A=[(w,m,q)for w in Y for m in(-1,0,1)for q in S];exec("def R(e):\n r={}\n for k in range(4):\n  r[(\"q0\"if k<2 else\"q1\")+\",\"+Y[k%2]]=A[e%18];e//=18\n return r");C={};H=[];E=[];exec("for s in range(b):\n for i in range(min(n,s+1)):\n  for x in range(min(n,s+1-i)):\n   k=(i,x)\n   if k not in C:C[k]=[list(\"1\"*x or\"_\"),0,\"q0\",0]\n   t,h,q,c=C[k]\n   if q in(\"H\",\"OPEN\"):continue\n   if h<0:t=[\"_\"]+t;h=0\n   if h>=len(t):t+=[\"_\"]\n   y=t[h];r=R(i).get(q+\",\"+y);E.append([s,i,x,q,h,y]+list(r or [\"?\",0,\"OPEN\"]))\n   if not r:q=\"OPEN\"\n   else:t[h]=r[0];h+=r[1];q=r[2];H+=([[i,x,s,c+1,\"\".join(t)]]if q==\"H\"else[])\n   C[k]=[t,h,q,c+1]");D={"P":"ALL-TM-DOVETAIL-2K","D":"fair prefix of all 2x2 TM over unary inputs","N":n,"B":b,"A":"2-state/2-symbol indices; input X_j=1^j","RUNS":len(C),"HALT":H[:32],"TRACE":E[-64:]};G=sum((i+1)*(c+1)for i,c in enumerate(J(D).encode()))%(10**18);Z=[G%2047,(2047-G%2047)%2047,0];D.update(G=G,R=[.5,round(math.log(G+1)*14.134725,6)],ZP=Z,BUG=0,PCC=1,ZE=int(Z[2]==0));open("All_Turing_Machines.clcert","w").write(J(D)+"\n");print(J(D))' "$N" "$B"
